func TestCheck_InvalidServerAndAPIURLs(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name    string
		envVars map[string]string
		wantErr string
	}{
		{
			name: "invalid server url scheme",
			envVars: map[string]string{
				"GITHUB_ACTIONS":    "true",
				"GITHUB_TOKEN":      "ghp_test",
				"GITHUB_SERVER_URL": "ftp://ghe.example.com",
			},
			wantErr: "invalid GITHUB_SERVER_URL",
		},
		{
			name: "missing host in api url",
			envVars: map[string]string{
				"GITHUB_ACTIONS": "true",
				"GITHUB_TOKEN":   "ghp_test",
				"GITHUB_API_URL": "https:///api/v3",
			},
			wantErr: "invalid GITHUB_API_URL",
		},
		{
			name: "unparseable url",
			envVars: map[string]string{
				"GITHUB_ACTIONS":    "true",
				"GITHUB_TOKEN":      "ghp_test",
				"GITHUB_SERVER_URL": "://bad-url",
			},
			wantErr: "invalid GITHUB_SERVER_URL",
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()

			err := NewWithEnv(env(tc.envVars)).Check()
			if err == nil || !strings.Contains(err.Error(), tc.wantErr) {
				t.Fatalf("expected error containing %q, got: %v", tc.wantErr, err)
			}
		})
	}
}
